Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), combine them into a single 7-bit integer, and write that integer into the `Uint8Array` at the current offset. Since 7 bits is less than 8, it fits perfectly into a single byte without padding.
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits for the `id` and the upper 3 bits for the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
  if (!Array.isArray(entities)) {
    throw new Error("Input must be an array");
  }

  // Calculate total size: 1 byte per entity (4 bits + 3 bits = 7 bits)
  const bufferSize = entities.length;
  const buffer = new Uint8Array(bufferSize);

  for (let i = 0; i < entities.length; i++) {
    const entity = entities[i];

    // Validate fields
    if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
      throw new Error(`Entity at index ${i} is missing id or size`);
    }

    // Masking to ensure we only use the correct bits
    // id: 4 bits (0-15) -> 0b00001111
    // size: 3 bits (0-7) -> 0b11100000
    const packed = (entity.size << 4) | entity.id;

    buffer[i] = packed;
  }

  return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
  if (!(buffer instanceof Uint8Array)) {
    throw new Error("Input must be a Uint8Array");
  }

  const entities = [];

  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];

    // Extract bits
    // id: lower 4 bits
    // size: upper 3 bits
    const id = byte & 0x0F;       // 0b00001111
    const size = (byte >> 4) & 0x07; // 0b00000111

    entities.push({ id, size });
  }

  return entities;
}

