### 1. The Web Worker (`workers/csv-parser.worker.js`)

This file runs in a separate thread. It receives the file content, parses it, and sends the result back to the main thread.

**`app/workers/csv-parser.worker.js`**

```javascript
import { parse } from 'papaparse'; // You will need to install this: npm install papaparse

self.onmessage = (event) => {
  const { fileContent } = event.data;

  try {
    // Parse the CSV string
    const results = parse(fileContent, {
      header: true,
      skipEmptyLines: true,
      dynamicTyping: true, // Automatically convert numbers to numbers
    });

    // Send the parsed data back to the main thread
    self.postMessage({
      type: 'success',
      data: results.data,
      headers: results.meta.fields,
    });
  } catch (error) {
    self.postMessage({
      type: 'error',
      message: error.message,
    });
  }
};
```

